	if f.b.Mode == cnfrt.ModeTree {
		r := f.row0(p)
		id := f.b.PostID(0)
		f.s.nodesCatalog[id-1] = r
		return id
	}
	addr := cnfrt.Addr(p)
	if id := f.b.Lookup(addr, 0); id != 0 {
		return id
	}
	var id uint32
	if f.b.Preorder() {
		id = f.b.PreID(0)
		f.b.Record(addr, 0, id)
	}
	r := f.row0(p)
	if !f.b.Preorder() {
		id = f.b.PostID(0)
		f.b.Record(addr, 0, id)
	}
	f.s.nodesCatalog[id-1] = r
