type catalogUnfreezer struct {
	s   *CatalogSnapshot
	err error
	// depth counts nested value nodes; it cannot exceed the number of
	// nodes unless a (corrupt) image contains a value-node cycle.
	depth int
	m0    []*Catalog
	m1    []*Item
	m2    []*Seller
}

func (u *catalogUnfreezer) bytes(x cnfrt.Span32) []byte {
	if x.Off == cnfrt.NilSpanOff {
		return nil
	}
	return []byte(u.s.rawStr(x))
}

func (u *catalogUnfreezer) filli0(r *flatDims, p *Dims) {
	p.W = r.FW
	p.H = r.FH
	p.D = r.FD
}

func (u *catalogUnfreezer) vi0(r flatDims) (x Dims) {
	u.filli0(&r, &x)
	return x
}

func (u *catalogUnfreezer) fill0(id uint32, p *Catalog) {
	r := &u.s.nodesCatalog[id-1]
	p.Version = u.s.str(r.FVersion)
	p.Items = u.u3(r.FItems)
}

func (u *catalogUnfreezer) pn0(id uint32) *Catalog {
	if id == 0 {
		return nil
	}
	if u.m0 == nil {
		u.m0 = make([]*Catalog, len(u.s.nodesCatalog))
	}
	if p := u.m0[id-1]; p != nil {
		return p
	}
	p := new(Catalog)
	u.m0[id-1] = p
	u.fill0(id, p)
	return p
}

func (u *catalogUnfreezer) vn0(id uint32) (x Catalog) {
	if id == 0 || u.depth > u.s.nodeCount() {
		if u.err == nil {
			u.err = fmt.Errorf("%w: value node cycle", cnfrt.ErrCycleDetected)
		}
		return x
	}
	u.depth++
	u.fill0(id, &x)
	u.depth--
	return x
}

func (u *catalogUnfreezer) fill1(id uint32, p *Item) {
	r := &u.s.nodesItem[id-1]
	p.ID = r.FID
	p.SKU = u.s.str(r.FSKU)
	p.Title = u.s.str(r.FTitle)
	p.Price = r.FPrice
	p.Stock = r.FStock
	p.Active = (r.FActive != 0)
	p.Tags = u.u7(r.FTags)
	p.Attrs = u.u8(r.FAttrs)
	p.Updated = cnfrt.DecodeTime(r.FUpdated, u.s.locs)
	p.Dims = u.vi0(r.FDims)
	p.Seller = u.pn2(r.FSeller)
}

func (u *catalogUnfreezer) pn1(id uint32) *Item {
	if id == 0 {
		return nil
	}
	if u.m1 == nil {
		u.m1 = make([]*Item, len(u.s.nodesItem))
	}
	if p := u.m1[id-1]; p != nil {
		return p
	}
	p := new(Item)
	u.m1[id-1] = p
	u.fill1(id, p)
	return p
}

func (u *catalogUnfreezer) vn1(id uint32) (x Item) {
	if id == 0 || u.depth > u.s.nodeCount() {
		if u.err == nil {
			u.err = fmt.Errorf("%w: value node cycle", cnfrt.ErrCycleDetected)
		}
		return x
	}
	u.depth++
	u.fill1(id, &x)
	u.depth--
	return x
}

func (u *catalogUnfreezer) fill2(id uint32, p *Seller) {
	r := &u.s.nodesSeller[id-1]
	p.ID = r.FID
	p.Name = u.s.str(r.FName)
	p.Country = u.s.str(r.FCountry)
}

func (u *catalogUnfreezer) pn2(id uint32) *Seller {
	if id == 0 {
		return nil
	}
	if u.m2 == nil {
		u.m2 = make([]*Seller, len(u.s.nodesSeller))
	}
	if p := u.m2[id-1]; p != nil {
		return p
	}
	p := new(Seller)
	u.m2[id-1] = p
	u.fill2(id, p)
	return p
}

func (u *catalogUnfreezer) vn2(id uint32) (x Seller) {
	if id == 0 || u.depth > u.s.nodeCount() {
		if u.err == nil {
			u.err = fmt.Errorf("%w: value node cycle", cnfrt.ErrCycleDetected)
		}
		return x
	}
	u.depth++
	u.fill2(id, &x)
	u.depth--
	return x
}

func (u *catalogUnfreezer) u3(x cnfrt.HashSpan) map[uint64]*Item {
	if x.KV.Off == cnfrt.NilSpanOff {
		return nil
	}
	src := u.s.pool0[int(x.KV.Off) : int(x.KV.Off)+int(x.KV.Len)]
	out := make(map[uint64]*Item, len(src))
	for i := range src {
		var v *Item
		v = u.pn1(src[i].V)
		out[src[i].K] = v
	}
	return out
}

func (u *catalogUnfreezer) u7(x cnfrt.Span32) []string {
	if x.Off == cnfrt.NilSpanOff {
		return nil
	}
	src := u.s.pool2[int(x.Off) : int(x.Off)+int(x.Len)]
	out := make([]string, len(src))
	for i := range src {
		out[i] = u.s.str(src[i])
	}
	return out
}

func (u *catalogUnfreezer) u8(x cnfrt.Span32) map[string]string {
	if x.Off == cnfrt.NilSpanOff {
		return nil
	}
	src := u.s.pool3[int(x.Off) : int(x.Off)+int(x.Len)]
	out := make(map[string]string, len(src))
	for i := range src {
		var v string
		v = u.s.str(src[i].V)
		out[u.s.str(src[i].K)] = v
	}
	return out
}

// UnfreezeCatalog rebuilds the root Catalog and everything reachable from it.
func (s *CatalogSnapshot) UnfreezeCatalog() (*Catalog, error) {
	if s.rootTable != 0 {
		return nil, fmt.Errorf("cnfgo: snapshot root is not a Catalog")
	}
	return s.RootCatalog().Unfreeze()
}

// UnfreezeItem rebuilds the root Item and everything reachable from it.
func (s *CatalogSnapshot) UnfreezeItem() (*Item, error) {
	if s.rootTable != 1 {
		return nil, fmt.Errorf("cnfgo: snapshot root is not a Item")
	}
	return s.RootItem().Unfreeze()
}

type catalogValidator struct {
	s          *CatalogSnapshot
	err        error
	cyclic     bool
	claims     []cnfrt.Claims
	workBudget uint64
}

func (v *catalogValidator) fail(what string) {
	if v.err == nil {
		v.err = fmt.Errorf("%w: %s", cnfrt.ErrBoundsViolation, what)
	}
}

func (v *catalogValidator) failErr(err error) {
	if v.err == nil {
		v.err = err
	}
}

func (v *catalogValidator) debit(n uint64) bool {
	if n > v.workBudget {
		v.fail("validation work budget exceeded")
		return false
	}
	v.workBudget -= n
	return true
}

func (v *catalogValidator) str(x cnfrt.Span32) bool {
	if x.Off&cnfrt.DictSpanBit != 0 {
		if v.s.dict == nil || !v.s.dict.ValidCapturedSpan(v.s.dictStrs, x) {
			v.fail("dict string span")
			return false
		}
		return true
	}
	if x.Off == cnfrt.NilSpanOff || x.End() > uint64(len(v.s.strBlob)) {
		v.fail("string span")
		return false
	}
	return true
}

func (v *catalogValidator) bool(x uint8) {
	if x > 1 {
		v.fail("boolean")
	}
}

func (v *catalogValidator) bytes(x cnfrt.Span32) {
	if !x.InBounds(len(v.s.strBlob)) {
		v.fail("byte span")
	}
}

func (v *catalogValidator) time(x cnfrt.FlatTime) {
	if !x.Valid(len(v.s.locs)) {
		v.fail("time")
	}
}

func (v *catalogValidator) addr(x cnfrt.FlatAddr) {
	if !x.Valid(len(v.s.zoned)) {
		v.fail("address")
	}
}

func (v *catalogValidator) debitAddr(x cnfrt.FlatAddr) bool {
	n := uint64(1)
	if x.Kind == cnfrt.AddrV6Zoned {
		n += uint64(len(v.s.zoned[x.ZonedIdx-1].Zone()))
	}
	return v.debit(n)
}

func (v *catalogValidator) prefix(x cnfrt.FlatPrefix) {
	if !x.Valid() {
		v.fail("prefix")
	}
}

func (v *catalogValidator) tableLen(tbl int) int {
	switch tbl {
	case 0:
		return len(v.s.nodesCatalog)
	case 1:
		return len(v.s.nodesItem)
	case 2:
		return len(v.s.nodesSeller)
	}
	return 0
}

// ref checks a node reference from node self of table owner: it must be in
// bounds and, unless cycles are allowed, satisfy childID > selfID within a table.
func (v *catalogValidator) ref(tbl int, id uint32, nilOK bool, self uint32, owner int) {
	switch {
	case id == 0 && !nilOK:
		v.fail("nil value node")
	case uint64(id) > uint64(v.tableLen(tbl)):
		v.fail("node ID out of range")
	case !v.cyclic && id != 0 && tbl == owner && id <= self:
		v.fail("childID > selfID invariant violated")
	}
}

func (v *catalogValidator) v3(x cnfrt.HashSpan, self uint32, tbl int) {
	if err := v.claims[0].Claim(x.KV, -1, true); err != nil {
		v.failErr(err)
		return
	}
	region := cnfrt.HashRegion(int(x.KV.Len))
	if err := v.claims[1].Claim(x.Idx, region, x.KV.Off == cnfrt.NilSpanOff); err != nil {
		v.failErr(err)
		return
	}
	var idx []uint32
	if region > 0 {
		idx = v.s.pool1[int(x.Idx.Off) : int(x.Idx.Off)+region]
		used := 0
		for _, slot := range idx {
			if slot > x.KV.Len {
				v.fail("hash index slot")
				return
			}
			if slot != 0 {
				used++
			}
		}
		// Exactly one slot per entry leaves at least half of the region
		// empty, so every probe sequence ends early.
		if used != int(x.KV.Len) {
			v.fail("hash index occupancy")
			return
		}
	}
	if x.KV.Len == 0 {
		return
	}
	kv := v.s.pool0[int(x.KV.Off) : int(x.KV.Off)+int(x.KV.Len)]
	for i := range kv {
		e := &kv[i]
		if i > 0 && cmp.Compare(kv[i-1].K, e.K) >= 0 {
			v.fail("map keys not strictly ascending")
			return
		}
		v.ref(1, e.V, true, self, tbl)
	}
	// Every entry must be found by the probe sequence of its key, as Get
	// searches it, within a linear probe budget.
	mask := uint64(region - 1)
	var totalProbes uint64
	probeBudget := uint64(8*len(kv) + 64)
	for i := range kv {
		h := cnfrt.HashUint64(uint64(kv[i].K), v.s.seed)
		found := false
		for probe := range uint64(region) {
			totalProbes++
			if totalProbes > probeBudget {
				v.fail("hash index probe budget exceeded")
				return
			}
			slot := idx[(h+probe)&mask]
			if slot == 0 {
				break
			}
			if slot == uint32(i+1) {
				found = true
				break
			}
		}
		if !found {
			v.fail("hash index does not locate a key")
			return
		}
	}
}

func (v *catalogValidator) v7(x cnfrt.Span32, self uint32, tbl int) {
	if err := v.claims[2].Claim(x, -1, true); err != nil {
		v.failErr(err)
		return
	}
	if x.Len == 0 {
		return
	}
	elems := v.s.pool2[int(x.Off) : int(x.Off)+int(x.Len)]
	for i := range elems {
		v.str(elems[i])
	}
}

func (v *catalogValidator) v8(x cnfrt.Span32, self uint32, tbl int) {
	if err := v.claims[3].Claim(x, -1, true); err != nil {
		v.failErr(err)
		return
	}
	if x.Len == 0 {
		return
	}
	kv := v.s.pool3[int(x.Off) : int(x.Off)+int(x.Len)]
	for i := range kv {
		e := &kv[i]
		if !v.str(e.K) || !v.debit(uint64(e.K.Len)+1) {
			return
		}
		if i > 0 && strings.Compare(v.s.rawStr(kv[i-1].K), v.s.rawStr(e.K)) >= 0 {
			v.fail("map keys not strictly ascending")
			return
		}
		v.str(e.V)
	}
}

func (v *catalogValidator) row0(r *flatCatalog, self uint32) {
	tbl := 0
	_ = tbl
	v.str(r.FVersion)
	v.v3(r.FItems, self, tbl)
}

func (v *catalogValidator) row1(r *flatItem, self uint32) {
	tbl := 1
	_ = tbl
	v.str(r.FSKU)
	v.str(r.FTitle)
	v.bool(r.FActive)
	v.v7(r.FTags, self, tbl)
	v.v8(r.FAttrs, self, tbl)
	v.time(r.FUpdated)
	v.ref(2, r.FSeller, true, self, tbl)
}

func (v *catalogValidator) row2(r *flatSeller, self uint32) {
	tbl := 2
	_ = tbl
	v.str(r.FName)
	v.str(r.FCountry)
}

func (s *CatalogSnapshot) validate() error {
	v := &catalogValidator{s: s, cyclic: s.flags&cnfrt.FlagCyclicAllowed != 0, claims: make([]cnfrt.Claims, 4), workBudget: 32*uint64(s.SizeBytes()) + 65536}
	for _, a := range s.zoned {
		v.workBudget += 32 * uint64(len(a.Zone()))
	}
	if s.dict != nil {
		// Strings of an allowed Dict are compared during validation too;
		// their budget stays linear in the dictionary size.
		v.workBudget += min(32*s.dict.Stats().Bytes, 64<<20)
	}
	v.claims[0] = cnfrt.NewClaims(len(s.pool0))
	v.claims[1] = cnfrt.NewClaims(len(s.pool1))
	v.claims[2] = cnfrt.NewClaims(len(s.pool2))
	v.claims[3] = cnfrt.NewClaims(len(s.pool3))
	for i := range s.nodesCatalog {
		v.row0(&s.nodesCatalog[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesItem {
		v.row1(&s.nodesItem[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	for i := range s.nodesSeller {
		v.row2(&s.nodesSeller[i], uint32(i+1))
		if v.err != nil {
			return v.err
		}
	}
	return nil
}

func (s *CatalogSnapshot) appendSections(secs []cnfrt.Section) []cnfrt.Section {
	if len(s.nodesCatalog) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 0, Count: uint32(len(s.nodesCatalog)), Data: cnfrt.ViewSliceLE(s.nodesCatalog)})
	}
	if len(s.nodesItem) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 1, Count: uint32(len(s.nodesItem)), Data: cnfrt.ViewSliceLE(s.nodesItem)})
	}
	if len(s.nodesSeller) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 2, Count: uint32(len(s.nodesSeller)), Data: cnfrt.ViewSliceLE(s.nodesSeller)})
	}
	if len(s.pool0) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 0, Count: uint32(len(s.pool0)), Data: cnfrt.ViewSliceLE(s.pool0)})
	}
	if len(s.pool1) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 1, Count: uint32(len(s.pool1)), Data: cnfrt.ViewSliceLE(s.pool1)})
	}
	if len(s.pool2) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 2, Count: uint32(len(s.pool2)), Data: cnfrt.ViewSliceLE(s.pool2)})
	}
	if len(s.pool3) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 3, Count: uint32(len(s.pool3)), Data: cnfrt.ViewSliceLE(s.pool3)})
	}
	if len(s.strBlob) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Count: uint32(len(s.strBlob)), Data: cnfrt.UnsafeStringBytes(s.strBlob)})
	}
	if ext := cnfrt.EncodeExt(s.locEntries, s.zoned); ext != nil {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionExt, ElemAlign: 4, Count: uint32(len(ext)), Data: ext})
	}
	return secs
}

func (s *CatalogSnapshot) sections() []cnfrt.Section {
	return s.appendSections(make([]cnfrt.Section, 0, 9))
}

func (s *CatalogSnapshot) header(extra uint32) cnfrt.Header {
	return cnfrt.Header{Flags: s.flags | extra, SchemaHash: SchemaHashCatalog, HashSeed: s.seed, RootTable: s.rootTable, RootID: s.rootID}
}

// WriteTo writes the snapshot as a .cnf image to w. It returns
// cnfrt.ErrClosed if s is a closed memory-mapped snapshot, or
// cnfrt.ErrDictRequired if s references a process-local cnfrt.Dict.
func (s *CatalogSnapshot) WriteTo(w io.Writer) (int64, error) {
	if s.mapping != nil && s.mapping.Closed() {
		return 0, cnfrt.ErrClosed
	}
	if s.flags&cnfrt.FlagHasDict != 0 {
		return 0, cnfrt.ErrDictRequired
	}
	var secBuf [9]cnfrt.Section
	n, err := cnfrt.WriteImage(w, s.header(0), s.appendSections(secBuf[:0]))
	runtime.KeepAlive(s)
	return n, err
}

// MarshalCNF returns the snapshot encoded as a .cnf image. It returns
// cnfrt.ErrClosed if s is a closed memory-mapped snapshot, or
// cnfrt.ErrDictRequired if s references a process-local cnfrt.Dict.
func (s *CatalogSnapshot) MarshalCNF() ([]byte, error) {
	if s.mapping != nil && s.mapping.Closed() {
		return nil, cnfrt.ErrClosed
	}
	if s.flags&cnfrt.FlagHasDict != 0 {
		return nil, cnfrt.ErrDictRequired
	}
	var secBuf [9]cnfrt.Section
	h, secs := s.header(0), s.appendSections(secBuf[:0])
	out, err := cnfrt.AppendImage(make([]byte, 0, cnfrt.ImageSize(h, secs)), h, secs)
	runtime.KeepAlive(s)
	return out, err
}

// WriteCatalogSnapshotAtomic writes s to path atomically (temporary file, fsync, rename,
// directory fsync), so concurrent MapCatalogFile calls never observe a partial
// file.
func WriteCatalogSnapshotAtomic(path string, s *CatalogSnapshot) error {
	return cnfrt.WriteSnapshotAtomic(path, func(w io.Writer) error {
		_, err := s.WriteTo(w)
		return err
	})
}

// MapCatalogFile memory-maps the .cnf file at path read-only and returns a
// snapshot over it. With cnfrt.VerifyTrustedHeader only the header and
// section geometry are checked; cnfrt.VerifyChecksum also verifies all
// section checksums. cnfrt.VerifyUntrusted copies the file to the heap,
// unmaps it and validates every reference, so arbitrary input is safe to
// read; the returned snapshot is then not memory-mapped.
//
// String getters of memory-mapped snapshots return copies. The mapping is
// released by Close or, failing that, when the snapshot becomes unreachable.
func MapCatalogFile(path string, mode cnfrt.VerifyMode) (*CatalogSnapshot, error) {
	m, err := unsafemmap.Open(path)
	if err != nil {
		return nil, err
	}
	if mode >= cnfrt.VerifyUntrusted {
		var data []byte
		err := unsafemmap.FaultSafe(func() error {
			data = cnfrt.AlignedCopy(m.Bytes())
			return nil
		})
		if cerr := m.Close(); err == nil {
			err = cerr
		}
		if err != nil {
			return nil, err
		}
		return trackCatalogSnapshot(loadCatalogSnapshot(data, mode))
	}
	var s *CatalogSnapshot
	err = unsafemmap.FaultSafe(func() (err error) {
		s, err = loadCatalogSnapshot(m.Bytes(), mode)
		return err
	})
	if err != nil {
		m.Close()
		return nil, err
	}
	mapped := m.IsMapped()
	s.mapping, s.isMmap, s.cloneStrs = m, mapped, mapped
	unsafemmap.AttachCleanup(s, m)
	return trackSharedCatalogSnapshot(s, nil)
}

// MapItemFile memory-maps the .cnf file at path read-only and returns a
// snapshot over it; see MapCatalogFile.
func MapItemFile(path string, mode cnfrt.VerifyMode) (*CatalogSnapshot, error) {
	return MapCatalogFile(path, mode)
}

// WriteItemSnapshotAtomic writes s to path atomically; see WriteCatalogSnapshotAtomic.
func WriteItemSnapshotAtomic(path string, s *CatalogSnapshot) error {
	return WriteCatalogSnapshotAtomic(path, s)
}

// UnmarshalCatalogSnapshot decodes a .cnf image. Tables and strings of the result alias
// data, which must not be modified while the snapshot is in use, except with
// cnfrt.VerifyUntrusted, which validates an aligned private copy.
func UnmarshalCatalogSnapshot(data []byte, mode cnfrt.VerifyMode) (*CatalogSnapshot, error) {
	if mode >= cnfrt.VerifyUntrusted {
		return trackCatalogSnapshot(loadCatalogSnapshot(cnfrt.AlignedCopy(data), mode))
	}
	return trackSharedCatalogSnapshot(loadCatalogSnapshot(data, mode))
}

func loadCatalogSnapshot(data []byte, mode cnfrt.VerifyMode) (*CatalogSnapshot, error) {
	h, infos, err := cnfrt.ParseHeader(data, mode, SchemaHashCatalog)
	if err != nil {
		return nil, err
	}
	return buildCatalogSnapshot(data, h, infos, mode)
}

// buildCatalogSnapshot assembles a snapshot from the parsed sections of an image.
func buildCatalogSnapshot(data []byte, h cnfrt.Header, infos []cnfrt.SectionInfo, mode cnfrt.VerifyMode) (*CatalogSnapshot, error) {
	var err error
	s := &CatalogSnapshot{flags: h.Flags, seed: h.HashSeed, rootTable: h.RootTable, rootID: h.RootID}
	for _, in := range infos {
		switch {
		case in.Kind == cnfrt.SectionTable && in.Tag == 0:
			s.nodesCatalog, err = unsafemmap.Cast[flatCatalog](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 1:
			s.nodesItem, err = unsafemmap.Cast[flatItem](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 2:
			s.nodesSeller, err = unsafemmap.Cast[flatSeller](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 0:
			s.pool0, err = unsafemmap.Cast[flatKVUint64ItemHashMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 1:
			s.pool1, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 2:
			s.pool2, err = unsafemmap.Cast[cnfrt.Span32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 3:
			s.pool3, err = unsafemmap.Cast[flatKVStringStringMap](data, in)
		case in.Kind == cnfrt.SectionStrBlob && in.Tag == 0:
			s.strBlob = unsafemmap.String(data, in)
		case in.Kind == cnfrt.SectionExt && in.Tag == 0:
			s.locEntries, s.zoned, err = cnfrt.DecodeExt(cnfrt.SectionData(data, in))
			s.locs = (&cnfrt.LocTable{Entries: s.locEntries}).Locations()
		default:
			err = fmt.Errorf("%w: unexpected section kind %d tag %d", cnfrt.ErrCorruptHeader, in.Kind, in.Tag)
		}
		if err != nil {
			return nil, err
		}
	}
	switch s.rootTable {
	case 0:
		if s.rootID == 0 || uint64(s.rootID) > uint64(len(s.nodesCatalog)) {
			return nil, fmt.Errorf("%w: root ID %d", cnfrt.ErrBoundsViolation, s.rootID)
		}
	case 1:
		if s.rootID == 0 || uint64(s.rootID) > uint64(len(s.nodesItem)) {
			return nil, fmt.Errorf("%w: root ID %d", cnfrt.ErrBoundsViolation, s.rootID)
		}
	default:
		return nil, fmt.Errorf("%w: root table %d", cnfrt.ErrSchemaMismatch, s.rootTable)
	}
	if mode >= cnfrt.VerifyUntrusted {
		if err := s.validate(); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// CompactItem is a 16-byte immutable value holding a complete frozen Item in a
// single string, so a map or slice of CompactItem values contains one pointer per
// value. Scalar, string, time and address fields of the root are read
// directly at constant offsets without allocating; everything else is
// reachable through View.
//
// Layout (slim format 0x03): a flags byte, the root's single 88-byte flat
// record, the string blob offset, optional dictToken / ext / seed headers,
// the 64-bit schema hash, a section presence bitmask, unsigned varint
// counts for non-empty sections, payloads ordered by descending alignment
// (8, 4, 2, 1), and a trailing 4-byte CRC32C.
type CompactItem struct {
	cnfRaw string
}

var compactItemSlimSpecs = [8]cnfrt.SlimSectionSpec{
	{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 0, ElemSize: 16},
	{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 0, ElemSize: 24},
	{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 2, ElemSize: 20},
	{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 1, ElemSize: 4},
	{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 2, ElemSize: 8},
	{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 3, ElemSize: 16},
	{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Tag: 0, ElemSize: 1},
	{Kind: cnfrt.SectionExt, ElemAlign: 1, Tag: 0, ElemSize: 1},
}

// SchemaHashCNF implements cnfrt.SchemaHasher.
func (CompactItem) SchemaHashCNF() uint64 { return SchemaHashCatalog }

// PackItem freezes src (as FreezeItem does) into a CompactItem.
func PackItem(src *Item, opts ...cnfrt.FreezeOption) (CompactItem, error) {
	return packItem(cnfrt.ModeDAG, src, opts)
}

// PackTreeItem freezes src as a tree (as FreezeTreeItem does) into a CompactItem.
func PackTreeItem(src *Item, opts ...cnfrt.FreezeOption) (CompactItem, error) {
	return packItem(cnfrt.ModeTree, src, opts)
}

// PackCyclicItem freezes src permitting directed cycles (as FreezeCyclicItem
// does) into a CompactItem.
func PackCyclicItem(src *Item, opts ...cnfrt.FreezeOption) (CompactItem, error) {
	return packItem(cnfrt.ModeCyclic, src, opts)
}

// packItem freezes src into the pooled scratch snapshot of a freezer and
// encodes it, so that the only allocation is the encoded value itself.
func packItem(mode cnfrt.FreezeMode, src *Item, opts []cnfrt.FreezeOption) (c CompactItem, err error) {
	if src == nil {
		return CompactItem{}, cnfrt.ErrNilRoot
	}
	if mode != cnfrt.ModeTree {
		cnfrt.Escape(src)
	}
	f := catalogFreezerPool.Get().(*catalogFreezer)
	defer func() {
		cnfrt.Recover(recover(), &err)
		if err != nil {
			c = CompactItem{}
		}
		f.reset()
		catalogFreezerPool.Put(f)
	}()
	f.b.Init(mode, 3, opts...)
	f.scratch = true
	f.b.ReuseStrBuf(f.strBuf)
	f.mn1(src)
	f.allocate()
	id := f.en1(src)
	f.finish()
	runtime.KeepAlive(src)
	if id != 1 {
		return CompactItem{}, fmt.Errorf("%w: unexpected compact root ID %d", cnfrt.ErrBoundsViolation, id)
	}
	s := f.s
	var secBuf [8]cnfrt.Section
	secs := secBuf[:0]
	if len(s.nodesCatalog) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 0, Count: uint32(len(s.nodesCatalog)), Data: cnfrt.ViewSliceLE(s.nodesCatalog)})
	}
	if len(s.nodesSeller) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 2, Count: uint32(len(s.nodesSeller)), Data: cnfrt.ViewSliceLE(s.nodesSeller)})
	}
	if len(s.pool0) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 0, Count: uint32(len(s.pool0)), Data: cnfrt.ViewSliceLE(s.pool0)})
	}
	if len(s.pool1) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 1, Count: uint32(len(s.pool1)), Data: cnfrt.ViewSliceLE(s.pool1)})
	}
	if len(s.pool2) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 2, Count: uint32(len(s.pool2)), Data: cnfrt.ViewSliceLE(s.pool2)})
	}
	if len(s.pool3) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 3, Count: uint32(len(s.pool3)), Data: cnfrt.ViewSliceLE(s.pool3)})
	}
	if len(s.strBlob) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Count: uint32(len(s.strBlob)), Data: cnfrt.UnsafeStringBytes(s.strBlob)})
	}
	if ext := cnfrt.EncodeExt(s.locEntries, s.zoned); ext != nil {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionExt, ElemAlign: 1, Count: uint32(len(ext)), Data: ext})
	}
	var flags uint8
	var dictToken uint64
	if s.flags&cnfrt.FlagHasDict != 0 {
		flags |= cnfrt.SlimFlagDict
		dictToken = s.dict.Token()
	}
	if s.flags&cnfrt.FlagCyclicAllowed != 0 {
		flags |= cnfrt.SlimFlagCyclic
	}
	if s.seed != cnfrt.DefaultSeed && (len(s.pool1) > 0) {
		flags |= cnfrt.SlimFlagSeed
	}
	buf, err := cnfrt.AppendSlimCompact(nil, flags, cnfrt.ViewSliceLE(s.nodesItem[:1]), dictToken, s.seed, SchemaHashCatalog, compactItemSlimSpecs[:], secs)
	f.strBuf = f.b.StrBuf()
	if err != nil {
		return CompactItem{}, err
	}
	return CompactItem{cnfRaw: cnfrt.UnsafeSealBytes(buf)}, nil
}

// BorrowCompactItem validates the compact prefix of raw and returns a CompactItem that
// aliases raw without copying. It is intended for zero-copy reads inside
// callbacks such as SlabMap.Borrow and FrozenMap.Borrow; the returned value
// must not be retained beyond the lifetime of raw.
func BorrowCompactItem(raw string) (CompactItem, error) {
	s, err := cnfrt.CheckSlimCompactString(raw, 89, SchemaHashCatalog)
	return CompactItem{cnfRaw: s}, err
}

// BorrowCompactItemBytes is BorrowCompactItem for a byte slice, without copying. The
// returned CompactItem aliases raw: it is valid only while raw is neither
// modified nor reused, typically for the duration of a SlabMap.Borrow
// callback, and must not be retained beyond it. Use ParseCompactItem on a copy
// to keep a value.
func BorrowCompactItemBytes(raw []byte) (CompactItem, error) {
	s, err := cnfrt.CheckSlimCompactBytes(raw, 89, SchemaHashCatalog)
	return CompactItem{cnfRaw: s}, err
}

// ParseCompactItem checks raw (as produced by Raw) and returns it as a CompactItem. The
// embedded image is verified according to mode. With cnfrt.VerifyUntrusted
// a value that references a cnfrt.Dict is rejected with
// cnfrt.ErrDictRequired unless that Dict is passed with cnfrt.AllowDict.
func ParseCompactItem(raw string, mode cnfrt.VerifyMode, opts ...cnfrt.ParseOption) (CompactItem, error) {
	c := CompactItem{cnfRaw: raw}
	if _, err := c.cnfLoad(mode, true, cnfrt.AllowedDict(opts)); err != nil {
		return CompactItem{}, err
	}
	return c, nil
}

// cnfCheck verifies the structure of the compact prefix (version, size,
// schema hash, dictionary registration and the offsets used by direct
// getters).
func (c CompactItem) cnfCheck() error {
	return cnfrt.CheckSlimCompactPrefix(c.cnfRaw, 89, SchemaHashCatalog)
}

func (c CompactItem) cnfU32(off int) uint32 {
	return binary.LittleEndian.Uint32([]byte(c.cnfRaw[off : off+4]))
}

func (c CompactItem) cnfExt() string {
	s := c.cnfRaw
	if len(s) < 101 || s[0]&cnfrt.SlimFlagExt == 0 {
		return ""
	}
	p := 93
	if s[0]&cnfrt.SlimFlagDict != 0 {
		p += cnfrt.SlimDictTokenSize
	}
	h := s[p : p+8]
	off := int(binary.LittleEndian.Uint32([]byte(h[0:4])))
	l := int(binary.LittleEndian.Uint32([]byte(h[4:8])))
	return s[off : off+l]
}

func (c CompactItem) cnfTime(off int) time.Time {
	b := c.cnfRaw[off : off+16]
	sec := int64(binary.LittleEndian.Uint64([]byte(b[0:8])))
	meta := binary.LittleEndian.Uint64([]byte(b[8:16]))
	if (meta>>30)&3 == cnfrt.LocUTC {
		return time.Unix(sec, int64(meta&0x3fffffff)).UTC()
	}
	return cnfrt.DecodeCompactTime(sec, meta, c.cnfExt())
}

func (c CompactItem) cnfLoad(mode cnfrt.VerifyMode, checkCRC bool, allow *cnfrt.Dict) (*CatalogSnapshot, error) {
	data := cnfrt.UnsafeStringBytes(c.cnfRaw)
	if mode >= cnfrt.VerifyUntrusted {
		data = cnfrt.AlignedCopy(data)
	}
	var infoBuf [8]cnfrt.SectionInfo
	h, dict, infos, err := cnfrt.ParseSlimCompact(data, 88, SchemaHashCatalog, 1, compactItemSlimSpecs[:], mode, checkCRC, allow, infoBuf[:0])
	if err != nil {
		return nil, err
	}
	s := &CatalogSnapshot{flags: h.Flags, seed: h.HashSeed, rootTable: h.RootTable, rootID: h.RootID, dict: dict, dictStrs: dict.Chunks()}
	if err := cnfrt.DecodeSliceLE(s.inlineRootItem[:], data[1:89]); err != nil {
		return nil, err
	}
	s.nodesItem = s.inlineRootItem[:]
	for _, in := range infos {
		switch {
		case in.Kind == cnfrt.SectionTable && in.Tag == 0:
			s.nodesCatalog, err = unsafemmap.Cast[flatCatalog](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 2:
			s.nodesSeller, err = unsafemmap.Cast[flatSeller](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 0:
			s.pool0, err = unsafemmap.Cast[flatKVUint64ItemHashMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 1:
			s.pool1, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 2:
			s.pool2, err = unsafemmap.Cast[cnfrt.Span32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 3:
			s.pool3, err = unsafemmap.Cast[flatKVStringStringMap](data, in)
		case in.Kind == cnfrt.SectionStrBlob && in.Tag == 0:
			s.strBlob = unsafemmap.String(data, in)
		case in.Kind == cnfrt.SectionExt && in.Tag == 0:
			s.locEntries, s.zoned, err = cnfrt.DecodeExt(cnfrt.SectionData(data, in))
			if err == nil {
				s.locs = (&cnfrt.LocTable{Entries: s.locEntries}).Locations()
			}
		default:
			err = fmt.Errorf("%w: unexpected section kind %d tag %d", cnfrt.ErrCorruptHeader, in.Kind, in.Tag)
		}
		if err != nil {
			return nil, err
		}
	}
	if mode >= cnfrt.VerifyUntrusted {
		if err := s.validate(); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// IsZero reports whether c is the zero value.
func (c CompactItem) IsZero() bool { return c.cnfRaw == "" }

// UsesDict reports whether c stores any strings in a process-local cnfrt.Dict.
func (c CompactItem) UsesDict() bool { return len(c.cnfRaw) > 0 && c.cnfRaw[0]&cnfrt.SlimFlagDict != 0 }

// Detach returns a self-contained CompactItem with all dictionary strings
// materialized into its local string blob. If c does not use a dictionary,
// Detach returns c. By default the result keeps the hash seed of c
// (DefaultSeed unless c carries an explicit seed) and time.Local, so
// detaching the same value twice yields identical bytes; caller opts
// override those defaults except that WithDict is always cleared so the
// result never references a cnfrt.Dict. It returns cnfrt.ErrUnknownDict
// if the dictionary of c has been closed.
func (c CompactItem) Detach(opts ...cnfrt.FreezeOption) (CompactItem, error) {
	if !c.UsesDict() {
		return c, nil
	}
	v, err := c.Unpack()
	if err != nil || v == nil {
		return CompactItem{}, err
	}
	merged := make([]cnfrt.FreezeOption, 0, len(opts)+3)
	merged = append(merged, cnfrt.WithHashSeed(cnfrt.SlimCompactSeed(c.cnfRaw, 89)), cnfrt.WithPreserveLocal())
	merged = append(merged, opts...)
	merged = append(merged, cnfrt.WithDict(nil))
	mode := cnfrt.ModeDAG
	if c.cnfRaw[0]&cnfrt.SlimFlagCyclic != 0 {
		mode = cnfrt.ModeCyclic
	}
	return packItem(mode, v, merged)
}

// Raw returns the encoded value. It can be stored and later passed to
// ParseCompactItem.
func (c CompactItem) Raw() string { return c.cnfRaw }

// Equal reports whether c and o hold identical encodings.
func (c CompactItem) Equal(o CompactItem) bool { return c.cnfRaw == o.cnfRaw }

// View returns a view of the root over the embedded image. The image is
// not copied, but a snapshot header is allocated; the direct getters of
// CompactItem do not allocate. View panics if c is corrupt or references a closed
// cnfrt.Dict (use TryView to get an error instead), and returns the zero
// view for the zero value.
func (c CompactItem) View() ItemView {
	if c.cnfRaw == "" {
		return ItemView{}
	}
	s, err := c.cnfLoad(cnfrt.VerifyTrustedHeader, false, nil)
	if err != nil {
		panic(err)
	}
	return s.view1(s.rootID)
}

// TryView is like View but returns an error instead of panicking:
// cnfrt.ErrUnknownDict if c references a closed cnfrt.Dict, or a header
// error if c is corrupt.
func (c CompactItem) TryView() (ItemView, error) {
	if c.cnfRaw == "" {
		return ItemView{}, nil
	}
	if err := c.cnfCheck(); err != nil {
		return ItemView{}, err
	}
	s, err := c.cnfLoad(cnfrt.VerifyTrustedHeader, false, nil)
	if err != nil {
		return ItemView{}, err
	}
	return s.view1(s.rootID), nil
}

// Snapshot loads the embedded image as a snapshot, verified according to
// mode; see ParseCompactItem for the options.
func (c CompactItem) Snapshot(mode cnfrt.VerifyMode, opts ...cnfrt.ParseOption) (*CatalogSnapshot, error) {
	return c.cnfLoad(mode, true, cnfrt.AllowedDict(opts))
}

// Unpack rebuilds the original Item. It returns cnfrt.ErrUnknownDict if c
// references a closed cnfrt.Dict.
func (c CompactItem) Unpack() (*Item, error) {
	if c.cnfRaw == "" {
		return nil, nil
	}
	s, err := c.Snapshot(cnfrt.VerifyTrustedHeader)
	if err != nil {
		return nil, err
	}
	return s.view1(s.rootID).Unfreeze()
}

// SizeCNF implements cnfrt.SelfCodec.
func (c CompactItem) SizeCNF() int { return len(c.cnfRaw) }

// AppendCNF implements cnfrt.SelfCodec.
func (c CompactItem) AppendCNF(dst []byte) []byte { return append(dst, c.cnfRaw...) }

// DecodeCNF implements cnfrt.SelfDecoder. It checks the compact prefix;
// use ParseCompactItem to verify the embedded image as well. src is retained.
func (c *CompactItem) DecodeCNF(src string) error {
	s, err := cnfrt.CheckSlimCompactString(src, 89, SchemaHashCatalog)
	if err == nil {
		c.cnfRaw = s
	}
	return err
}

// CodecCNF implements cnfrt.CodecProvider. Maps such as cnfrt.FrozenMap and
// cnfrt.SlabMap use the returned codec for CompactItem values by default.
func (CompactItem) CodecCNF() cnfrt.Codec[CompactItem] { return compactItemCodec{} }

// compactItemCodec is the cnfrt.Codec of CompactItem. It also implements
// cnfrt.UntrustedValidator, verifying the embedded image completely and
// rejecting values that reference a cnfrt.Dict, and cnfrt.AlignedCodec,
// so that stored values keep their image 8-byte aligned.
type compactItemCodec struct{}

func (compactItemCodec) Size(c CompactItem) int { return len(c.cnfRaw) }

func (compactItemCodec) Append(dst []byte, c CompactItem) []byte { return append(dst, c.cnfRaw...) }

func (compactItemCodec) Decode(src string) (CompactItem, error) {
	s, err := cnfrt.CheckSlimCompactString(src, 89, SchemaHashCatalog)
	return CompactItem{cnfRaw: s}, err
}

func (compactItemCodec) ValidateUntrusted(src string) error {
	if src == "" {
		return nil
	}
	_, err := ParseCompactItem(src, cnfrt.VerifyUntrusted)
	return err
}

func (compactItemCodec) AlignCNF() int { return 8 }

// ID returns the ID field of the root without allocating.
func (c CompactItem) ID() uint64 {
	if c.cnfRaw == "" {
		var zero uint64
		return zero
	}
	return binary.LittleEndian.Uint64([]byte(c.cnfRaw[1:9]))
}

// SKU returns the SKU field of the root without allocating.
func (c CompactItem) SKU() string {
	s := c.cnfRaw
	if len(s) < 93 {
		return ""
	}
	o, l := cnfrt.U32S(s[33:]), cnfrt.U32S(s[37:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return ""
		}
		return cnfrt.ResolveDictSpan(s, 93, o, l)
	}
	i := int(cnfrt.U32S(s[89:])) + int(o)
	return s[i : i+int(l)]
}

// SKUEquals reports whether the SKU field equals v without allocating.
func (c CompactItem) SKUEquals(v string) bool {
	s := c.cnfRaw
	if len(s) < 93 {
		return v == ""
	}
	o, l := cnfrt.U32S(s[33:]), cnfrt.U32S(s[37:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return v == ""
		}
		return cnfrt.ResolveDictSpan(s, 93, o, l) == v
	}
	i := int(cnfrt.U32S(s[89:])) + int(o)
	return s[i:i+int(l)] == v
}

// SKULen returns the length of the SKU field without allocating.
func (c CompactItem) SKULen() int {
	if c.cnfRaw == "" {
		return 0
	}
	return int(c.cnfU32(37))
}

